package in.foodcart.api; import in.foodcart.data.*; import in.foodcart.service.AuthService; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/customers/me") public class CustomerController {private final AuthService auth;private final HistoryRepository history;private final VendorRepository vendors;private final OrderRepository orders;public CustomerController(AuthService a,HistoryRepository h,VendorRepository v,OrderRepository o){auth=a;history=h;vendors=v;orders=o;}@GetMapping("/orders") List<OrderEntity> orders(@RequestHeader("Authorization") String h){return orders.findByCustomerIdOrderByCreatedAtDesc(auth.actor(h,"CUSTOMER"));}@GetMapping("/recent-vendors") List<Map<String,Object>> recent(@RequestHeader("Authorization") String h){return history.findByCustomerIdOrderByLastOrderedAtDesc(auth.actor(h,"CUSTOMER")).stream().map(x->{VendorEntity v=vendors.findById(x.vendorId).orElse(null);return Map.<String,Object>of("vendor",v,"lastOrderedAt",x.lastOrderedAt,"totalOrders",x.totalOrders);}).toList();}}
